import {normalizeTutorialTraining} from './tutorial-training-state.mjs';
import {SUMMON_GUARANTEE,summonProbabilityForDraw} from './summon-probability.mjs';
import {normalizeTowerWeekly,mergeTowerWeekly} from './tower-weekly-state.mjs';
import {normalizeTower,mergeTowerRecords} from './tower-state.mjs';
import {freshOnboarding,normalizeOnboarding} from './onboarding-state.mjs';
import {normalizeShop} from './shop-state.mjs';
import {equipmentUpgradeCost} from './equipment-upgrades.mjs';
import {normalizeChallenges} from './campaign-challenges.mjs';
import {STAGE_BY_ID} from './campaign-data.mjs';
import {equipmentBonuses,normalizeEquipmentRolls,rollEquipment} from './equipment-stats.mjs';
import {normalizePassives,passiveBonuses} from './campaign-passives.mjs';
import {normalizeArtifacts,grantArtifact,ARTIFACTS,artifactBonuses,equippedArtifact} from './campaign-artifacts.mjs';
import {normalizePets} from './campaign-pet-data.mjs';
import {grantPetXP,petExperience,PETS} from './campaign-pet-data.mjs';
import {normalizeDaily} from './daily-quests.mjs';
import {SOLO_HEROES,SOLO_KEY,BASE_STATS,LEVEL_GROWTH,SOLO_BALANCE,SOLO_SKILLS,skillById,experience,equipmentClass,QUALITY,ITEMS,itemInfo,upgradeCosts} from './campaign-growth-data.mjs';
export function freshSolo(){return {version:1,tutorialTraining:normalizeTutorialTraining(),towerWeekly:normalizeTowerWeekly(),tower:normalizeTower(),onboarding:freshOnboarding(),shop:normalizeShop(),challenges:normalizeChallenges(),redeemedCodes:[],daily:normalizeDaily(),passives:normalizePassives(),petRestEpoch:0,petRestAfterStage:null,petRestStages:[],artifacts:{},equippedArtifact:null,activePetId:null,pets:[],mirrorEquipped:false,coins:300,tickets:0,owned:['fire'],selected:'fire',lineup:['fire'],cleared:[],firstTickets:[],choiceClaimed:false,pity:{},serial:2,heroes:Object.fromEntries(SOLO_HEROES.map(h=>[h,{exp:0,skills:{[`${h}-0-0`]:0},slots:{q:`${h}-0-0`,e:null,r:null},equipment:{weapon:null,armor:null,artifact:null},receivedFrom:null}])),bag:[{id:'item-1',type:'chestMedium',count:2},{id:'item-2',type:'xpMedium',count:3}]};}
const integer=(n,max=1e7)=>Number.isSafeInteger(n)&&n>=0?Math.min(n,max):0;
export function normalizeSolo(raw){const p=freshSolo();if(raw?.version!==1)return p;p.tutorialTraining=normalizeTutorialTraining(raw.tutorialTraining);p.towerWeekly=normalizeTowerWeekly(raw.towerWeekly);p.tower=normalizeTower(raw.tower);p.onboarding=normalizeOnboarding(raw.onboarding,{legacy:!raw.onboarding});p.shop=normalizeShop(raw.shop);p.challenges=normalizeChallenges(raw.challenges);p.redeemedCodes=Array.isArray(raw.redeemedCodes)?[...new Set(raw.redeemedCodes.filter(v=>v==='秘境决斗666'))]:[];p.passives=normalizePassives(raw.passives);p.coins=integer(raw.coins);p.tickets=integer(raw.tickets);p.serial=integer(raw.serial);p.owned=[...new Set(['fire',...(raw.owned||[]).filter(h=>SOLO_HEROES.includes(h))])];p.selected=p.owned.includes(raw.selected)?raw.selected:'fire';p.lineup=[...new Set((Array.isArray(raw.lineup)?raw.lineup:[p.selected]).filter(h=>p.owned.includes(h)))].slice(0,2);if(!p.lineup.length)p.lineup=[p.selected];p.cleared=[...new Set((raw.cleared||[]).filter(x=>Number.isInteger(x)&&x>=1&&!!STAGE_BY_ID[x]))];p.firstTickets=[...new Set((raw.firstTickets||[]).filter(x=>Number.isInteger(x)&&x>=1&&!!STAGE_BY_ID[x]))];p.choiceClaimed=!!raw.choiceClaimed;p.petRestEpoch=integer(raw.petRestEpoch);p.petRestAfterStage=integer(raw.petRestAfterStage,22)||null;p.petRestStages=[...new Set((raw.petRestStages??p.cleared).filter(v=>Number.isInteger(v)&&v>=1&&!!STAGE_BY_ID[v]))];p.artifacts=normalizeArtifacts(raw.artifacts);if(raw.artifacts===undefined&&p.cleared.includes(4))grantArtifact(p,'mirror');p.pets=normalizePets(raw.pets);p.activePetId=p.pets.some(v=>v.id===raw.activePetId)?raw.activePetId:null;p.equippedArtifact=equippedArtifact({...p,equippedArtifact:raw.equippedArtifact,mirrorEquipped:!!raw.mirrorEquipped});p.mirrorEquipped=p.equippedArtifact==='mirror';p.pity=Object.fromEntries(SOLO_HEROES.map(h=>[h,integer(raw.pity?.[h],19)]));
 p.bag=Array.isArray(raw.bag)?raw.bag.filter(i=>i&&typeof i.id==='string'&&(ITEMS[i.type]||i.type==='equipment'&&['weapon','armor'].includes(i.slot)&&['melee','staff'].includes(i.role))).map(i=>i.type==='equipment'?({...i,rolls:normalizeEquipmentRolls(i.rolls),count:1,quality:integer(i.quality,5),setTier:integer(i.setTier,2),collection:i.collection===2?2:undefined,rank:integer(i.rank,3),level:integer(i.level,10)}):({id:i.id,type:i.type,count:Math.max(1,integer(i.count,9999))})):[];
 const assignedGear=new Set();for(const h of SOLO_HEROES){const a=raw.heroes?.[h];if(!a)continue;const v=p.heroes[h];v.exp=integer(a.exp,1e9);v.receivedFrom=SOLO_HEROES.includes(a.receivedFrom)?a.receivedFrom:null;v.skills={};for(const s of SOLO_SKILLS[h])if(a.skills?.[s.id]!==undefined)v.skills[s.id]=integer(a.skills[s.id],5);v.skills[`${h}-0-0`]??=0;for(const key of ['q','e','r']){const s=skillById(a.slots?.[key]);v.slots[key]=s?.hero===h&&s.key===key&&v.skills[s.id]!==undefined?s.id:key==='q'?`${h}-0-0`:null;}for(const slot of ['weapon','armor']){const item=p.bag.find(i=>i.id===a.equipment?.[slot]);v.equipment[slot]=p.owned.includes(h)&&item?.slot===slot&&item.role===equipmentClass(h)&&!assignedGear.has(item.id)?item.id:null;if(v.equipment[slot])assignedGear.add(item.id);}}
 p.daily=normalizeDaily(raw.daily);p.serial=Math.max(p.serial,...p.pets.map(i=>Number(i.id.slice(4))||0),...p.bag.map(i=>Number(i.id.slice(5))||0));return p;
}
export function loadSolo(storage){try{return normalizeSolo(JSON.parse(storage.getItem(SOLO_KEY)||'null'));}catch{return freshSolo();}}
export function saveSolo(storage,p){try{const old=JSON.parse(storage.getItem(SOLO_KEY)||'null'),current=normalizeChallenges(p.challenges),saved=normalizeChallenges(old?.challenges);p.challenges=Object.fromEntries(Object.keys(current).map(k=>[k,Math.max(current[k],saved[k])]));p.tower=mergeTowerRecords(p.tower,old?.tower);p.towerWeekly=mergeTowerWeekly(p.towerWeekly,old?.towerWeekly);storage.setItem(SOLO_KEY,JSON.stringify(p));return true;}catch{return false;}}
export function addItem(p,item){if(!ITEMS[item.type]&&item.type!=='equipment')throw Error('未知物品');const artifactId=Object.keys(ARTIFACTS).find(id=>ARTIFACTS[id].item===item.type);if(artifactId)grantArtifact(p,artifactId);if(item.type==='ticket'){p.tickets+=item.count||1;return null;}const old=item.type!=='equipment'&&p.bag.find(i=>i.type===item.type);if(old){old.count+=item.count||1;return old;}const v={...item,...(item.type==='equipment'?{rolls:item.rolls?normalizeEquipmentRolls(item.rolls):rollEquipment()}:{}),id:'item-'+(++p.serial),count:item.count||1};p.bag.push(v);return v;}
export function heroStats(p,hero=p.selected){const h=p.heroes[hero],level=experience(h.exp).level,[hp,mp]=BASE_STATS[hero],weapon=equipmentBonuses(p.bag.find(i=>i.id===h.equipment.weapon)),armor=equipmentBonuses(p.bag.find(i=>i.id===h.equipment.armor)),artifact=artifactBonuses(p),passive=passiveBonuses(p);return {level,maxHp:Math.round((artifact.health+hp*(1+LEVEL_GROWTH.health*(level-1)+armor.healthRatio))*SOLO_BALANCE.health),maxMp:Math.round(Math.round(mp*(1+LEVEL_GROWTH.mana*(level-1)))*SOLO_BALANCE.mana),attack:Math.round((artifact.attack+10*(1+LEVEL_GROWTH.attack*(level-1))+weapon.attack)*SOLO_BALANCE.attack),power:.6*SOLO_BALANCE.attack*(1+LEVEL_GROWTH.attack*(level-1)+weapon.attack/10+artifact.attack/10),crit:Math.min(.35,.05+weapon.crit+passive.crit),critDamage:1.5+passive.critDamage,manaRegen:passive.manaRegen,lifesteal:weapon.lifesteal,regen:passive.regen+armor.regen,attackSpeed:1+weapon.attackSpeed,armor:armor.armor};}
export function grantXP(p,hero,value){const h=p.heroes[hero],before=experience(h.exp).level;h.exp=Math.min(1e9,h.exp+Math.max(0,Math.floor(value)));return experience(h.exp).level-before;}
export function learnSkill(p,hero,id){const s=skillById(id),h=p.heroes[hero];if(!s||s.hero!==hero||!p.owned.includes(hero))throw Error('英雄或技能不可用');if(h.skills[id]!==undefined)throw Error('已经学习');if(p.coins<s.cost)throw Error('金币不足');p.coins-=s.cost;h.skills[id]=0;if(!h.slots[s.key])h.slots[s.key]=id;}
export function equipSkill(p,hero,id){const s=skillById(id),h=p.heroes[hero];if(!s||s.hero!==hero||h.skills[id]===undefined)throw Error('先学习此技能');h.slots[s.key]=id;}
export function upgradeSkill(p,hero,id){const s=skillById(id),h=p.heroes[hero],rank=h.skills[id];if(!s||rank===undefined)throw Error('先学习此技能');if(rank>=5)throw Error('已达到五次强化上限');const cost=upgradeCosts[s.row][rank];if(p.coins<cost)throw Error('金币不足');p.coins-=cost;h.skills[id]++;}
export function equipItem(p,hero,id){const item=p.bag.find(i=>i.id===id);if(item?.type!=='equipment')throw Error('请选择装备');if(!p.owned.includes(hero))throw Error('请选择已拥有的英雄');if(item.role!==equipmentClass(hero))throw Error('职业不符：此装备只适用于'+(item.role==='melee'?'近战':'法杖')+'职业');for(const h of Object.values(p.heroes))for(const slot of ['weapon','armor'])if(h.equipment[slot]===id)h.equipment[slot]=null;p.heroes[hero].equipment[item.slot]=id;}
export function usePetExperienceItem(p,id,petId){const item=p.bag.find(i=>i.id===id),info=item&&itemInfo(item),pet=p.pets.find(v=>v.id===petId);if(info?.kind!=='petXp')throw Error('请选择宠物经验药水');if(!pet)throw Error('请先选择一只已捕获灵宠');if(petExperience(pet.exp).level>=30)throw Error('这只灵宠已达到等级上限');grantPetXP(p,petId,info.value);take(p,item);return `${PETS[pet.kind].name} 获得 ${info.value} 经验 · Lv.${petExperience(pet.exp).level}`;}
function take(p,item,n=1){item.count-=n;if(item.count<=0){p.bag=p.bag.filter(i=>i.id!==item.id);for(const h of Object.values(p.heroes))for(const k of ['weapon','armor'])if(h.equipment[k]===item.id)h.equipment[k]=null;}}
export function sellItem(p,id){const item=p.bag.find(i=>i.id===id),info=item&&itemInfo(item);if(!info?.sell)throw Error('此物品不可出售');for(const h of Object.values(p.heroes))if(Object.values(h.equipment).includes(id))throw Error('请先卸下装备');p.coins+=info.sell;take(p,item);return info.sell;}
export function useItem(p,id,hero=p.selected,player=null){const item=p.bag.find(i=>i.id===id),info=item&&itemInfo(item);if(!info)throw Error('物品不存在');if(info.kind==='heroChoice')throw Error('请选择一位未拥有英雄');if(info.kind==='coins')p.coins+=info.value;else if(info.kind==='xp')grantXP(p,hero,info.value);else if(['health','mana'].includes(info.kind)){if(!player)throw Error('此补给在关卡中使用');const k=info.kind==='health'?'hp':'mp',max=info.kind==='health'?'maxHp':'maxMp';if(player[k]>=player[max])throw Error('当前已经充足');player[k]=Math.min(player[max],player[k]+Math.round(player[max]*info.value));}else throw Error('请在锻造炉使用材料');take(p,item);return info;}
export function chooseHero(p,id,hero){const item=p.bag.find(i=>i.id===id);if(item?.type!=='heroChoice'||!SOLO_HEROES.includes(hero)||p.owned.includes(hero))throw Error('请选择尚未拥有的英雄');p.owned.push(hero);take(p,item);}
export function transferPower(p,source,target){if(source===target||!p.owned.includes(source)||!p.owned.includes(target))throw Error('请选择另一位已拥有英雄');const a=p.heroes[source],b=p.heroes[target];if(experience(b.exp).level>=5)throw Error('接收者必须低于5级');if(b.receivedFrom)throw Error('此英雄已经接收过功力');if(a.receivedFrom)throw Error('接收的功力不可再次转传');if(!a.exp)throw Error('传出者没有可传经验');b.exp=Math.min(1e9,b.exp+a.exp);b.receivedFrom=source;a.exp=0;}
export function summonSolo(p,target,count=1,random=Math.random){if(![1,10].includes(count)||!SOLO_HEROES.includes(target)||p.owned.includes(target))throw Error('请选择未拥有英雄，单抽或十连');if(p.tickets<count)throw Error('抽奖券不足');const results=[];for(let i=0;i<count;i++){p.tickets--;const n=(p.pity[target]||0)+1,roll=random();if(n>=SUMMON_GUARANTEE||roll<summonProbabilityForDraw(n)){p.pity[target]=0;p.owned.push(target);results.push({hero:target,name:SOLO_HEROES.indexOf(target)});break;}p.pity[target]=n;const type=['stoneSmall','xpSmall','chestSmall'][Math.min(2,Math.floor(random()*3))];addItem(p,{type,count:1});results.push({type});}return results;}
export function forgeRecipe(p,id){const item=p.bag.find(i=>i.id===id);if(item?.type!=='equipment'||(item.rank||0)>=3)return null;const rank=item.rank||0;return {item,rank:rank+1,type:['stoneSmall','stoneMedium','stoneHigh'][rank],need:[10,10,10][rank]};}
export function forgeItem(p,id,stoneId){const recipe=forgeRecipe(p,id);if(!recipe)throw Error('请选择尚未满三品的装备');const {item,type,need,rank}=recipe,stone=stoneId===undefined?p.bag.find(v=>v.type===type):p.bag.find(v=>v.id===stoneId);if(stone?.type!==type)throw Error('请放入'+ITEMS[type].name);if(stone.count<need)throw Error(`需要${need}枚${ITEMS[type].name}`);take(p,stone,need);item.rank=rank;return `锻造成功 · ${itemInfo(item).name} · ${rank}品`;}
export function levelEquipment(p,id){const i=p.bag.find(i=>i.id===id);if(i?.type!=='equipment'||(i.level||0)>=10)throw Error('装备已满级或不可强化');const cost=equipmentUpgradeCost(i);if(p.coins<cost)throw Error('金币不足');p.coins-=cost;i.level=(i.level||0)+1;}
export function combineStones(p,type){const next={stoneSmall:'stoneMedium',stoneMedium:'stoneHigh'}[type],i=p.bag.find(v=>v.type===type);if(!next||!i||i.count<3)throw Error('需要3枚同阶灵石');take(p,i,3);addItem(p,{type:next,count:1});}
export function synthesisRecipe(p,slots){if(!Array.isArray(slots)||slots.length!==3||slots.some(id=>!id))return null;const items=slots.map(id=>p.bag.find(i=>i.id===id));if(items.some(i=>!i)||items.some(i=>i.type!==items[0].type))return null;const type={stoneSmall:'stoneMedium',stoneMedium:'stoneHigh'}[items[0].type];if(!type)return null;const counts=new Map();for(const i of items)counts.set(i.id,(counts.get(i.id)||0)+1);if(items.some(i=>i.count<counts.get(i.id)))return null;return {type,counts};}
export function synthesizeStones(p,slots){const recipe=synthesisRecipe(p,slots);if(!recipe)throw Error('放入3枚同阶的小灵石或中等灵石，数量需足够');for(const [id,count] of recipe.counts)take(p,p.bag.find(i=>i.id===id),count);addItem(p,{type:recipe.type,count:1});return `合成成功 · ${ITEMS[recipe.type].name} ×1`;}

